-- SmartCart AI SQLite database export
-- Created: 2026-10-09T14:13:37.633209
-- Source database is not modified by this export.

BEGIN TRANSACTION;
CREATE TABLE auth_otps (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                identifier TEXT NOT NULL,
                channel TEXT NOT NULL,
                otp_hash TEXT NOT NULL,
                expires_at INTEGER NOT NULL,
                attempts INTEGER NOT NULL DEFAULT 0,
                created_at INTEGER NOT NULL,
                verified_at INTEGER
            );
CREATE TABLE customer_addresses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id INTEGER NOT NULL,
                full_name TEXT NOT NULL,
                phone TEXT NOT NULL,
                address_line1 TEXT NOT NULL,
                address_line2 TEXT,
                city TEXT NOT NULL,
                state TEXT NOT NULL,
                postal_code TEXT NOT NULL,
                country TEXT NOT NULL DEFAULT 'India',
                is_default INTEGER NOT NULL DEFAULT 0,
                created_at INTEGER NOT NULL,
                FOREIGN KEY(customer_id)
                    REFERENCES customers(id)
                    ON DELETE CASCADE
            );
CREATE TABLE customers (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE COLLATE NOCASE,
                phone TEXT UNIQUE,
                full_name TEXT,
                google_sub TEXT UNIQUE,
                email_verified INTEGER NOT NULL DEFAULT 0,
                phone_verified INTEGER NOT NULL DEFAULT 0,
                created_at INTEGER NOT NULL,
                updated_at INTEGER NOT NULL
            );
CREATE TABLE price_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            price REAL NOT NULL,
            recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (product_id) REFERENCES products(id)
        );
CREATE TABLE product_attributes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,

            product_id INTEGER NOT NULL,

            attribute_name TEXT NOT NULL,
            attribute_value TEXT NOT NULL,

            UNIQUE(
                product_id,
                attribute_name,
                attribute_value
            ),

            FOREIGN KEY(product_id)
                REFERENCES products(id)
                ON DELETE CASCADE
        );
CREATE TABLE product_categories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,

            product_id INTEGER NOT NULL,

            main_category TEXT NOT NULL,
            subcategory TEXT,
            segment TEXT,

            UNIQUE(
                product_id,
                main_category,
                subcategory,
                segment
            ),

            FOREIGN KEY(product_id)
                REFERENCES products(id)
                ON DELETE CASCADE
        );
CREATE TABLE product_colors (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            colour TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE product_images (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            image_url TEXT NOT NULL,
            image_order INTEGER NOT NULL, colour TEXT, color TEXT,
            UNIQUE(product_id, image_order),
            FOREIGN KEY (product_id)
                REFERENCES products(id) ON DELETE CASCADE
        );
CREATE TABLE product_specs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            spec_name TEXT NOT NULL,
            spec_value TEXT NOT NULL,

            UNIQUE(product_id, spec_name),

            FOREIGN KEY(product_id)
                REFERENCES products(id)
                ON DELETE CASCADE
        );
CREATE TABLE product_variants (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            variant_name TEXT,
            colour TEXT,
            color TEXT,
            size TEXT,
            storage TEXT,
            ram TEXT,
            sku TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        category TEXT NOT NULL,
        brand TEXT,
        platform TEXT NOT NULL,
        price REAL NOT NULL,
        mrp REAL NOT NULL,
        rating REAL DEFAULT 0,
        reviews INTEGER DEFAULT 0,
        lifespan_years REAL DEFAULT 2,
        energy_kwh REAL DEFAULT 0,
        review_text TEXT DEFAULT '',
        product_url TEXT DEFAULT '#',
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , image TEXT, description TEXT, stock INTEGER DEFAULT 1);
CREATE TABLE store_prices (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            store_id INTEGER NOT NULL,
            price REAL NOT NULL,
            recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(product_id, store_id),
            FOREIGN KEY (product_id)
                REFERENCES products(id) ON DELETE CASCADE,
            FOREIGN KEY (store_id)
                REFERENCES stores(id) ON DELETE CASCADE
        );
CREATE TABLE stores (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE
        );
CREATE INDEX idx_products_category
        ON products(category)
    ;
CREATE INDEX idx_products_price
        ON products(price)
    ;
CREATE INDEX idx_products_rating
        ON products(rating)
    ;
CREATE INDEX idx_history_product_date
        ON price_history(product_id, recorded_at)
    ;
CREATE INDEX idx_store_prices_product
        ON store_prices(product_id)
    ;
CREATE INDEX idx_product_images_product
        ON product_images(product_id)
    ;
CREATE INDEX idx_price_history_product
        ON price_history(product_id)
    ;
CREATE INDEX idx_history_product
        ON price_history(product_id)
    ;
CREATE INDEX idx_auth_otps_identifier
            ON auth_otps(identifier, channel)
        ;
CREATE INDEX idx_auth_otps_expiry
            ON auth_otps(expires_at)
        ;
CREATE INDEX idx_product_specs_product
        ON product_specs(product_id)
    ;
CREATE INDEX idx_product_specs_name
        ON product_specs(spec_name)
    ;
CREATE INDEX idx_product_categories_product
        ON product_categories(product_id)
    ;
CREATE INDEX idx_product_categories_main
        ON product_categories(main_category)
    ;
CREATE INDEX idx_product_attributes_product
        ON product_attributes(product_id)
    ;
CREATE INDEX idx_product_attributes_name
        ON product_attributes(attribute_name)
    ;
CREATE INDEX idx_products_brand
        ON products(brand)
        ;
CREATE INDEX idx_images_product_order
        ON product_images(product_id, image_order)
        ;
CREATE INDEX idx_attr_product_name
            ON product_attributes(
                product_id,
                attribute_name
            )
            ;
CREATE INDEX idx_attr_name_value
            ON product_attributes(
                attribute_name,
                attribute_value
            )
            ;
DELETE FROM "sqlite_sequence";
COMMIT;
